27	function toggle(name: string): void {
28	  const next = new Set(selected.value);
29	  if (next.has(name)) next.delete(name);
30	  else next.add(name);
31	  selected.value = next;
32	  copied.value = false;
33	}
34	
35	const chosen = computed(() => components.filter((c) => selected.value.has(c.name)));
36	// "All" uses the whole `components.css` barrel; otherwise the checked per-component sheets.
37	const active = computed(() => (allComponents.value ? components : chosen.value));
38	const hasSelection = computed(() => allComponents.value || chosen.value.length > 0);
39	// The lean token sheet omits icons, so any active icon-using component needs component-icons.css. The
40	// full sheet already carries every icon.
41	const needsIconSheet = computed(
42	  () => tokenSheet.value === "lean" && active.value.some((c) => c.needsIcons),
43	);
44	
45	const combineUrl = computed(() => {
46	  // Track the latest release (no version pin) — pin yourself for production. jsDelivr serves raw file
47	  // paths (it ignores the package `exports` map), and every sheet ships under `dist/`.
48	  const c = "npm/@pantoken/components/dist";
49	  const files = [
50	    `npm/@pantoken/css/dist/${tokenSheet.value === "lean" ? "style.lean.css" : "style.css"}`,
51	  ];
52	  if (includeBase.value) files.push(`${c}/base.css`);
53	  if (needsIconSheet.value) files.push(`${c}/component-icons.css`);
54	  if (allComponents.value) files.push(`${c}/components.css`);
55	  else for (const comp of chosen.value) files.push(`${c}/${comp.name}.css`);
56	  return `https://cdn.jsdelivr.net/combine/${files.join(",")}`;
57	});
58	
59	const output = computed(() =>
60	  format.value === "link"
61	    ? `<link rel="stylesheet" href="${combineUrl.value}">`
62	    : `@import url("${combineUrl.value}");`,
63	);
64	
65	async function copy(): Promise<void> {
66	  try {
67	    await navigator.clipboard.writeText(output.value);
68	    copied.value = true;
69	    setTimeout(() => (copied.value = false), 1500);
70	  } catch {
71	    // Clipboard blocked — the code stays selectable in the block.
72	  }
73	}
