 * @cssproperty --pantoken-toggle-w <length> — The toggle track width.
 * @cssproperty --pantoken-toggle-bw <length> — The toggle border width.
 * @cssproperty --pantoken-toggle-inset <length> — The handle inset from each track edge.
 * @cssproperty --pantoken-toggle-handle <length> — The computed handle diameter.
 * @cssstate checked
 * @cssstate indeterminate
 * @cssstate disabled
 * @accessibility A native `<input type="checkbox">` drives `:checked`, `:indeterminate`, and `:disabled`; set `el.indeterminate = true` in JavaScript for the mixed state, and note that `-readonly` is styling only since checkboxes have no native readonly attribute.
 * @example
 * <label class="pfx-checkbox"><input type="checkbox" checked> Checked</label>
 * @related radio — The single-select counterpart.
 */
.pfx-checkbox {
  display: inline-flex;
  align-items: center;
  gap: var(--instui-component-checkbox-gap);
  color: var(--instui-component-checkbox-label-base-color);
