/**
 * Canonical npm metadata for every publishable `@pantoken/*` package, shared by the writer
 * (`sync-repository-metadata.ts`) and the gate (`check-repository-metadata.ts`) so the two can never
 * drift. The gate runs on every PR, so whatever the writer emits is exactly what the gate enforces.
 */

/** `repository.url` — required verbatim for npm OIDC provenance; a missing value silently breaks it. */
export const REPOSITORY_URL = "git+https://github.com/thedannywahl/pantoken.git";

/** `homepage` — the docs site root, identical for every package. */
export const HOMEPAGE_URL = "https://pantoken.iywahl.com";

/** `bugs` — the shared issue tracker. */
export const BUGS_URL = "https://github.com/thedannywahl/pantoken/issues";

/** `engines` — mirrors the repo-root Node constraint. */
export const ENGINES: Readonly<Record<string, string>> = { node: ">=22.18.0" };

export interface ExpectedRepository {
  type: "git";
  url: string;
  directory: string;
}

/** The `repository` object for a package, keyed by its repo-relative POSIX path (e.g. `formats/css`). */
export function expectedRepository(directory: string): ExpectedRepository {
  return { type: "git", url: REPOSITORY_URL, directory };
}

interface SurfaceManifest {
  exports?: unknown;
  files?: unknown;
}

/**
 * A package "ships CSS" when its published surface (`exports` or `files`) references a `.css` file —
 * those styles are a side effect a bundler must not tree-shake away.
 */
export function shipsCss(manifest: SurfaceManifest): boolean {
  const surface = JSON.stringify(manifest.exports ?? null) + JSON.stringify(manifest.files ?? null);
  return surface.includes(".css");
}

export type SideEffects = false | string[];

/** `["**/*.css"]` for CSS-shipping packages (keep the styles), `false` otherwise (pure, tree-shakeable). */
export function expectedSideEffects(manifest: SurfaceManifest): SideEffects {
  return shipsCss(manifest) ? ["**/*.css"] : false;
}

import fs from "node:fs/promises";
import path from "node:path";

import {
  BUGS_URL,
  ENGINES,
  expectedRepository,
  expectedSideEffects,
  HOMEPAGE_URL,
} from "./repository-metadata.ts";
import { isPublishablePackage, loadWorkspacePackages } from "./workspace-packages.ts";

type Manifest = Record<string, unknown>;

/**
 * Rebuild the manifest's key order so the new keys land next to related ones (localized diffs):
 * `homepage`/`bugs` after `repository`, `sideEffects`/`engines` after `type`. Keys already present
 * keep their original position (only their value updates); any target key missing an anchor is
 * appended at the end as a fallback.
 */
function reorder(manifest: Manifest): Manifest {
  const originalKeys = new Set(Object.keys(manifest));
  const afterRepository = ["homepage", "bugs"];
  const afterType = ["sideEffects", "engines"];
  const emitted = new Set<string>();

  const out: Manifest = {};
  const push = (key: string): void => {
    if (key in manifest && !emitted.has(key)) {
      out[key] = manifest[key];
      emitted.add(key);
    }
  };

  for (const key of Object.keys(manifest)) {
    if (emitted.has(key)) continue;
    push(key);
    if (key === "repository") for (const k of afterRepository) if (!originalKeys.has(k)) push(k);
    if (key === "type") for (const k of afterType) if (!originalKeys.has(k)) push(k);
  }

  // Fallback: anchors absent (e.g. no `type`) — append whatever hasn't been emitted yet.
  for (const key of [...afterRepository, ...afterType]) push(key);

  return out;
}

async function syncPackage(relDir: string): Promise<boolean> {
  const manifestPath = path.resolve(relDir, "package.json");
  const raw = await fs.readFile(manifestPath, "utf8");
  const manifest = JSON.parse(raw) as Manifest;

  manifest.repository = expectedRepository(relDir);
  manifest.homepage = HOMEPAGE_URL;
  manifest.bugs = BUGS_URL;
  // Read the CSS surface from the original manifest before we touch anything else.
  manifest.sideEffects = expectedSideEffects(manifest);
  manifest.engines = { ...ENGINES };
  manifest.publishConfig = {
    ...(manifest.publishConfig as Manifest | undefined),
    provenance: true,
  };

  const next = `${JSON.stringify(reorder(manifest), null, 2)}\n`;
  if (next === raw) return false;

  await fs.writeFile(manifestPath, next);
  return true;
}

async function main(): Promise<void> {
  const { packages } = await loadWorkspacePackages();
  const publishable = packages.filter((pkg) => isPublishablePackage(pkg));

  let changed = 0;
  for (const pkg of publishable) {
    if (await syncPackage(pkg.path)) {
      changed += 1;
      process.stdout.write(`updated ${pkg.path}/package.json\n`);
    }
  }

  process.stdout.write(
    `Repository metadata sync complete: ${changed} changed, ${publishable.length - changed} already current (${publishable.length} publishable).\n`,
  );
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});

import fs from "node:fs/promises";
import path from "node:path";

import {
  BUGS_URL,
  ENGINES,
  expectedSideEffects,
  HOMEPAGE_URL,
  REPOSITORY_URL,
} from "./repository-metadata.ts";
import { isPublishablePackage, loadWorkspacePackages } from "./workspace-packages.ts";

interface PackageManifest {
  repository?: unknown;
  homepage?: unknown;
  bugs?: unknown;
  sideEffects?: unknown;
  engines?: unknown;
  publishConfig?: unknown;
  license?: unknown;
  type?: unknown;
  files?: unknown;
  description?: unknown;
  exports?: unknown;
}

function repositoryUrlOf(repository: unknown): string | undefined {
  if (typeof repository === "string") return repository;
  if (!repository || typeof repository !== "object") return undefined;
  const url = (repository as { url?: unknown }).url;
  return typeof url === "string" ? url : undefined;
}

function repositoryDirectoryOf(repository: unknown): string | undefined {
  if (!repository || typeof repository !== "object") return undefined;
  const dir = (repository as { directory?: unknown }).directory;
  return typeof dir === "string" ? dir : undefined;
}

const eq = (a: unknown, b: unknown): boolean => JSON.stringify(a) === JSON.stringify(b);

async function main() {
  const { packages } = await loadWorkspacePackages();
  const publishable = packages.filter((pkg) => isPublishablePackage(pkg));

  const violations: string[] = [];

  for (const pkg of publishable) {
    const manifestPath = path.resolve(pkg.path, "package.json");
    const raw = await fs.readFile(manifestPath, "utf8");
    const m = JSON.parse(raw) as PackageManifest;

    const fail = (msg: string): void => {
      violations.push(`${pkg.name} (${pkg.path}/package.json): ${msg}`);
    };

    // Linkage + provenance metadata.
    if (repositoryUrlOf(m.repository) !== REPOSITORY_URL) {
      fail(`repository.url is ${JSON.stringify(repositoryUrlOf(m.repository) ?? "")}, expected ${JSON.stringify(REPOSITORY_URL)}`);
    }
    if (repositoryDirectoryOf(m.repository) !== pkg.path) {
      fail(`repository.directory is ${JSON.stringify(repositoryDirectoryOf(m.repository) ?? "")}, expected ${JSON.stringify(pkg.path)}`);
    }
    if (m.homepage !== HOMEPAGE_URL) {
      fail(`homepage is ${JSON.stringify(m.homepage ?? "")}, expected ${JSON.stringify(HOMEPAGE_URL)}`);
    }
    if (m.bugs !== BUGS_URL) {
      fail(`bugs is ${JSON.stringify(m.bugs ?? "")}, expected ${JSON.stringify(BUGS_URL)}`);
    }

    // Build-hint metadata.
    const wantSideEffects = expectedSideEffects(m);
    if (!eq(m.sideEffects, wantSideEffects)) {
      fail(`sideEffects is ${JSON.stringify(m.sideEffects ?? null)}, expected ${JSON.stringify(wantSideEffects)}`);
    }
    if (!eq(m.engines, ENGINES)) {
      fail(`engines is ${JSON.stringify(m.engines ?? null)}, expected ${JSON.stringify(ENGINES)}`);
    }
    const provenance = (m.publishConfig as { provenance?: unknown } | undefined)?.provenance;
    if (provenance !== true) {
      fail("publishConfig.provenance is not true");
    }

    // Regression insurance on the already-consistent fields.
    if (m.license !== "MIT") fail(`license is ${JSON.stringify(m.license ?? "")}, expected "MIT"`);
    if (m.type !== "module") fail(`type is ${JSON.stringify(m.type ?? "")}, expected "module"`);
    if (!Array.isArray(m.files) || m.files.length === 0) fail("files is missing or empty");
    if (typeof m.description !== "string" || m.description.length === 0) {
      fail("description is missing or empty");
    }
  }

  if (violations.length > 0) {
    console.error("Repository metadata check failed for publishable packages:");
    for (const violation of violations) {
      console.error(`- ${violation}`);
    }
    process.exitCode = 1;
    return;
  }

  process.stdout.write(
    `Repository metadata check passed for ${publishable.length} publishable packages.\n`,
  );
}

main().catch((error) => {
  console.error(error instanceof Error ? error.message : String(error));
  process.exitCode = 1;
});

