/**
 * Rebuild the manifest's key order so the new keys land next to related ones (localized diffs):
 * `homepage`/`bugs` after `repository`, `sideEffects`/`engines` after `type`. Keys already present
 * keep their original position (only their value updates); any target key missing an anchor is
 * appended at the end as a fallback.
 */
function reorder(manifest: Manifest): Manifest {
  const originalKeys = new Set(Object.keys(manifest));
  const afterRepository = ["homepage", "bugs"];
  const afterType = ["sideEffects", "engines"];
  const emitted = new Set<string>();

  const out: Manifest = {};
  const push = (key: string): void => {
    if (key in manifest && !emitted.has(key)) {
      out[key] = manifest[key];
      emitted.add(key);
    }
  };

  for (const key of Object.keys(manifest)) {
    if (emitted.has(key)) continue;
    push(key);
    if (key === "repository") for (const k of afterRepository) if (!originalKeys.has(k)) push(k);
    if (key === "type") for (const k of afterType) if (!originalKeys.has(k)) push(k);
  }

  // Fallback: anchors absent (e.g. no `type`) — append whatever hasn't been emitted yet.
  for (const key of [...afterRepository, ...afterType]) push(key);

  return out;
}

